import java.util.concurrent.RecursiveTask;
import java.util.concurrent.ForkJoinPool;

class ArraySumTask extends RecursiveTask<Long> {
    final long[] array; final int start, end;
    ArraySumTask(long[] arr, int s, int e) { this.array = arr; this.start = s; this.end = e; }
    @Override protected Long compute() {
        if (end - start <= 1000) {
            long sum = 0; for (int i = start; i < end; i++) sum += array[i]; return sum;
        }
        int mid = (start + end) / 2;
        var left = new ArraySumTask(array, start, mid);
        var right = new ArraySumTask(array, mid, end);
        left.fork();
        return right.compute() + left.join();
    }
}

